function cwPrEditAI(ctx){const d=cwD(ctx.params.id);if(!d)return[];const pc=cwPrPriceCheck(d,cwDX(d).priceLow,cwDX(d).priceHigh);return[pc.ok?{k:'auto',t:'Price check passed',b:h(cwPrice(d))+' meets the Victorian rules against the recorded estimate.'}:{k:'check',t:'Price check',b:pc.problems.map(h).join('<br>')},{k:'draft',t:'Description draft',b:'Press "Rewrite description with GeeVee" for a draft from the recorded facts. Nothing is invented.'}]}
