/* ---------- property detail ---------- */
function cwPrTabLabel(d,t){const x=cwDX(d);const enq=state.cw.enquiries.filter(e=>e.dealId===d.id).length+(state.offers||[]).filter(o=>o.dealId===d.id).length;return({property:'Property',owner:'Owner',purchaser:'Purchaser',enquiries:`Enquiries / Attendees / Offers (${enq})`,analytics:'Analytics',notes:`Agent Notes (${x.notes.length})`,photos:`Photos (${x.photos.length})`,open_homes:'Open Homes',documents:'Documents',compliance:'Compliance',typeform:'TypeForm',buyer_match:`Buyer Match (${typeof gvxMatchBuyers==='function'?gvxMatchBuyers(d).length:0})`,notifications:'Notifications',activity:'Activity'})[t]}
function cwPrDetail(ctx){const base=cwPrBase(ctx);const d=cwD(ctx.params.id);if(!d)return cwHeader('Property not found','This property is not in the CRM.',cwGoBtn('Back',base,'primary'));
 const tabs=base==='/collings-properties'?CW_PR_TABS_COLL:CW_PR_TABS_MINE;const tab=tabs.includes(ctx.q.tab)?ctx.q.tab:'property';const x=cwDX(d);
 const acts=base==='/collings-properties'?[['Edit property','cwGo',base+'/edit/'+d.id,'primary'],['Duplicate','cwPrDup',d.id+'|'+base],['Withdraw','cwPrWithdraw',d.id],['Mark as sold','cwPrSold',d.id],['Delete','cwPrDelete',d.id+'|'+base,'warn']]:[['Edit property','cwGo',base+'/edit/'+d.id,'primary'],['Duplicate','cwPrDup',d.id+'|'+base],['Draft article','cwPrArticle',d.id],['Withdraw','cwPrWithdraw',d.id],['Under contract','cwPrContract',d.id],['Mark as sold','cwPrSold',d.id],['Delete','cwPrDelete',d.id+'|'+base,'warn']];
 const body=({property:cwPrTProperty,owner:cwPrTOwner,purchaser:cwPrTPurchaser,enquiries:cwPrTEnq,analytics:cwPrTAnalytics,notes:cwPrTNotes,photos:cwPrTPhotos,open_homes:cwPrTOpen,documents:cwPrTDocs,compliance:cwPrTComp,typeform:cwPrTType,buyer_match:cwPrTMatch,notifications:cwPrTNotify,activity:cwPrTActivity})[tab](d,base);
 return `<div class="cw-prop-head"><div><div class="cw-row" style="margin-bottom:6px">${cwStatusTag(x.status)}${tag(x.type,'outline')}${tag(d.stage,'')}${x.trashed?tag('In trash','red'):''}</div><h1 style="font-size:24px">${h(cwAddr(d))}</h1><div class="cw-row small muted" style="margin-top:6px"><b class="num" style="color:#152f36">${h(cwPrice(d))}</b>${cwPrFeat(d)}</div></div><div class="cw-prop-actions">${acts.map(a=>cwBtn(a[0],a[1],a[2],(a[3]||'')+' sm')).join('')}</div></div>
 ${cwTabs('pr:tab',tabs.map(t=>[t,cwPrTabLabel(d,t)]),{active:tab,route:v=>base+'/'+d.id+'?tab='+v})}${body}`}
function cwPrDetailAI(ctx){const d=cwD(ctx.params.id);if(!d)return[];const x=cwDX(d),base=cwPrBase(ctx),out=[];
 if(['New lead','Connected'].includes(d.stage)&&findP(d.contactId))out.push({k:'call',t:'Seller lead: call, no message',b:h(cwPName(d.contactId))+' gets a call from you. GeeVee drafts nothing to new seller leads.',a:[['Call '+h(cwPName(d.contactId).split(' ')[0]),'call',d.contactId,'primary']]});
 const miss=cwPrMissing(d);if(miss.length&&!['New lead','Connected','Lost'].includes(d.stage))out.push({k:'check',t:miss.length+' compliance items missing',b:miss.map(h).join('<br>'),a:[['Compliance','cwGo',base+'/'+d.id+'?tab=compliance']]});
 const pc=cwPrPriceCheck(d,x.priceLow,x.priceHigh);out.push(pc.ok?{k:'auto',t:'Price check passed',b:h(cwPrice(d))+' is within 10% and not below the estimate of '+cwMoney(pc.est)+'.'}:{k:'check',t:'Price check failed',b:pc.problems.map(h).join('<br>')});
 if(!x.descDraft&&(x.description||'').length<200)out.push({k:'draft',t:'Listing description',b:'GeeVee can write a fuller draft from the recorded facts and questionnaire. You accept or discard it.',a:[['Write draft','cwPrAiDesc',d.id]]});
 if(typeof gvxMatchBuyers==='function'){const ms=gvxMatchBuyers(d).filter(m=>m.ok&&!m.liveOffer);if(cwPrListedLive(d)&&ms.length)out.push({k:'draft',t:ms.length+' buyers with a recorded reason',b:'Drafts go to Today for your approval. Opted-out buyers and buyers with a live offer are left out.',a:[['Buyer match','cwGo',base+'/'+d.id+'?tab=buyer_match']]});else if(!cwPrListedLive(d))out.push({k:'info',t:'No buyer marketing yet',b:h(d.address)+' is not advertised ('+h(d.stage)+'), so GeeVee will not draft buyer messages about it.'})}
 if(d.stage==='For sale'&&!state.cw.openHomes.some(o=>o.dealId===d.id&&Date.parse(o.day)>Date.now()))out.push({k:'check',t:'No upcoming open home',b:'Add one on the Open Homes tab. GeeVee can then answer inspection questions on its own.'});
 return out}
cwPage('/properties/:id',{title:ctx=>cwD(ctx.params.id)?.address||'Property',group:'props',render:cwPrDetail,ai:cwPrDetailAI});
cwPage('/collings-properties/:id',{title:ctx=>cwD(ctx.params.id)?.address||'Property',group:'props',render:cwPrDetail,ai:cwPrDetailAI});

function cwPrTProperty(d,base){const x=cwDX(d),ch=x.channels||{},ag=cwAgentNames();const link='https://doma.com.au/p/'+d.id.toLowerCase();
 return `${x.descDraft?cwCard(ico('sparkles','sm')+' GeeVee draft description',`<p class="small" style="white-space:pre-wrap">${h(x.descDraft)}</p>`,`<div class="cw-row">${cwBtn('Use this','cwPrDescAccept',d.id,'sm primary')}${cwBtn('Discard','cwPrDescDiscard',d.id,'sm')}</div>`):''}
 <div class="cw-two">
 ${cwCard('Public Share Link',`<div class="cw-row"><input class="field" style="flex:1" readonly value="${h(link)}" aria-label="Public share link">${cwBtn(ico('copy','sm')+' Copy','cwPrCopy',link,'sm')}</div>`)}
 ${cwCard('Property Images',x.photos.length?`<div class="cw-gallery">${x.photos.slice(0,4).map(p=>`<figure><div class="cw-thumb big" style="height:80px;border-radius:0">${h(p.name.slice(0,18))}</div></figure>`).join('')}</div>`:cwEmpty('No images available for this property'),`<div class="cw-row">${cwGoBtn('Edit gallery',base+'/'+d.id+'?tab=photos','sm')}</div>`)}
 ${cwCard('Visibility (On-Market)',`${[['internal','Internal Marketing'],['portal','Collings Portal'],['rea','realestate.com.au'],['domain','domain.com.au'],['collings','Collings.com.au']].map(([k,l])=>`<div class="list-row"><div class="list-main"><strong>${l}</strong></div>${(ch[k]??(['internal','portal'].includes(k)||x.visibility))?tag('Shown','green'):tag('Hidden','')}${cwBtn((ch[k]??(['internal','portal'].includes(k)||x.visibility))?'Hide':'Show','cwPrChan',d.id+'|'+k,'sm')}</div>`).join('')}${cwPrBlocking(d).length?`<p class="hint" style="margin-top:8px">Portals stay hidden until the listing can go live: ${h(cwPrBlocking(d).join(', '))} missing.</p>`:''}`)}
 ${cwCard('Compliance checklist',CW_PR_COMP.map(k=>`<div class="list-row"><div class="list-main"><strong>${h(k)}</strong></div>${(d.compliance||{})[k]?tag('Received','green'):(x.compNA||[]).includes(k)?tag('N/A',''):tag(CW_PR_BLOCK.includes(k)?'Blocks go-live':'Not received',CW_PR_BLOCK.includes(k)?'red':'yellow')}</div>`).join(''),cwGoBtn('Open compliance',base+'/'+d.id+'?tab=compliance','sm'))}
 ${cwCard('Campaign Representatives',`<div class="cw-form" data-cwform="prag"><div class="cw-grid">${['Primary Agent','Secondary Agent (Optional)','Third Agent (Optional)'].map((l,i)=>`<div class="cw-ff ${i===0?'full':''}"><label class="form-label" for="prag-${i}">${l}</label><select id="prag-${i}" name="a${i}" class="field full">${(i?['None',...ag]:ag).map(a=>`<option ${(x.agents[i]||'None')===a?'selected':''}>${h(a)}</option>`).join('')}</select></div>`).join('')}</div></div>`,cwBtn('Save','cwPrAgents',d.id,'sm primary'))}
 ${cwCard('Internal Notes (Optional)',`<textarea id="pr-internal" class="field textarea full" aria-label="Internal notes">${h(x.internalNote||'')}</textarea>`,cwBtn('Save','cwPrInternal',d.id,'sm primary'))}
 </div>
 ${cwCard('Property Price Statement',`${x.docs.pps.length?x.docs.pps.map(f=>`<div class="list-row"><div class="number-circle">${ico('file','sm')}</div><div class="list-main"><strong>${h(f.name)}</strong><div class="sub">${cwDate(f.at)} · ${h(f.by)}</div></div></div>`).join(''):cwEmpty('No Property Price Statement uploaded yet.')}<div class="sep"></div><label class="form-label" for="pr-pps">Upload New Property Price Statement</label><div class="cw-row"><input id="pr-pps" type="file" class="field" accept=".pdf">${cwBtn('Upload','cwPrPps',d.id,'sm primary')}</div>`)}
 ${cwCard('About the Property',`<h3 style="margin-bottom:6px">${h(x.headline)}</h3><p class="small" style="white-space:pre-wrap">${h(x.description)}</p>`,cwGoBtn('Edit description',base+'/edit/'+d.id,'sm'))}
 ${cwCard('Property Information',cwKV([['Bedrooms',x.beds],['Bathrooms',x.baths],['Car spaces',x.cars+(x.parkingType&&x.parkingType!=='Select type'?' ('+h(x.parkingType)+')':'')],['Land area',x.land?x.land+' m²':''],['Floor area',x.floor?x.floor+' m²':''],['Year built',x.year],['Property type',h(x.type)],['Listing ID',h(d.id)],['Legacy ID',h(d.legacyId)]]))}
 ${cwCard('Listing Details',cwKV([['Status',cwStatusTag(x.status)],['Type',h(x.saleType)],['Method of sale',h(x.method)],['Price',h(cwPrice(d))],['Commission',x.commission.kind==='Percentage'?h(x.commission.rate+'% '+x.commission.gst):h(cwMoney(x.commission.rate)+' '+x.commission.gst)],['Days on market',x.dom||''],['Source',h(d.source)],['Next step',h(d.next||'')]]))}
 ${cwCard('Location',cwKV([['Address',h(d.address)],['Suburb',h(d.suburb)],['State',h(d.state||'VIC')],['Postcode',h(d.postcode||'')],['Publish',h(x.publish)]]))}`}
cwOn('cwPrCopy',link=>{try{navigator.clipboard?.writeText(link)}catch(e){}toast('Share link copied.')});
cwOn('cwPrChan',id=>{const [did,k]=id.split('|');const d=findD(did);if(!d)return;const x=cwDX(d);x.channels=x.channels||{};const cur=x.channels[k]??(['internal','portal'].includes(k)||x.visibility);if(!cur&&['rea','domain','collings'].includes(k)&&cwPrBlocking(d).length){toast('Cannot show on portals: '+cwPrBlocking(d).join(' and ')+' missing.');return}x.channels[k]=!cur;cwPrLog(d,(cur?'Hidden from ':'Shown on ')+k);cwPersist()});
cwOn('cwPrAgents',id=>{const d=findD(id);if(!d)return;const r=document.querySelector('[data-cwform="prag"]');const a=[0,1,2].map(i=>r.querySelector(`[name="a${i}"]`).value).filter(v=>v&&v!=='None');cwDX(d).agents=[...new Set(a)];d.owner=a[0];cwPrLog(d,'Campaign representatives: '+a.join(', '));cwPersist('Agents saved.')});
cwOn('cwPrInternal',id=>{const d=findD(id);if(!d)return;cwDX(d).internalNote=document.getElementById('pr-internal').value;cwPrLog(d,'Internal note updated');cwPersist('Internal note saved.')});
cwOn('cwPrPps',id=>{const d=findD(id);const f=document.getElementById('pr-pps')?.files?.[0];if(!d)return;if(!f){toast('Choose the Property Price Statement PDF first.');return}cwDX(d).docs.pps.unshift({id:cwId('DOC'),name:f.name,size:Math.round(f.size/1024)+' KB',at:cwNowISO(),by:CW_ME});d.compliance['Property Price Statement']=true;cwPrLog(d,'Property Price Statement uploaded: '+f.name);cwPersist('Property Price Statement uploaded. File name only in this prototype.')});
cwOn('cwPrAiDesc',id=>{const d=findD(id);if(!d)return;const x=cwDX(d);x.descDraft=cwPrDescFrom({headline:x.headline,address:d.address,suburb:d.suburb,beds:x.beds,baths:x.baths,cars:x.cars,land:x.land,internal:x.internal,external:x.external,qSchools:x.questionnaire.schools})+(x.questionnaire.best?' The owners love '+x.questionnaire.best+'.':'');audit('auto','GeeVee drafted a description for '+d.address,'From recorded facts only. Waiting for the agent.');cwPersist('Draft ready on the Property tab.');if(ui.cwRoute&&!/tab=property/.test(ui.cwRoute))cwGo(cwPrBase(cwCurrent().ctx)+'/'+d.id+'?tab=property')});
cwOn('cwPrDescAccept',id=>{const d=findD(id);const x=cwDX(d);x.description=x.descDraft;delete x.descDraft;cwPrLog(d,'Description updated from GeeVee draft (agent accepted)');cwPersist('Description updated.')});
cwOn('cwPrDescDiscard',id=>{const d=findD(id);delete cwDX(d).descDraft;cwPersist('Draft discarded.')});

