cwOn('cwPrLinkNew',id=>cwModal('cwPrLink',id));
cwModalDef('cwPrLink',id=>{const [did,kind]=id.split('|');return{title:kind==='owner'?'Add owner':'Add purchaser',body:cwForm('prlink',[{n:'contactId',l:'Existing contact',t:'select',o:[['','Create a new contact'],...cwContacts().map(p=>[p.id,p.name+' · '+p.suburb])],full:true},{n:'name',l:'New contact name'},{n:'phone',l:'Mobile',t:'tel'},{n:'email',l:'Email',t:'email'}])+'<p class="hint">Pick an existing contact, or fill the name to create one.</p>',foot:cwBtn('Cancel','close')+cwBtn('Add','cwPrLinkSave',id,'primary')}});
cwOn('cwPrLinkSave',id=>{const [did,kind]=id.split('|');const d=findD(did);const fs=[{n:'contactId',t:'select'},{n:'name',l:'Name'},{n:'phone',l:'Mobile',t:'tel'},{n:'email',l:'Email',t:'email'}];const v=cwRead('prlink',fs);if(!v)return;let p=findP(v.contactId);
 if(!p){if(!v.name){cwU().draft.prlink=v;cwU().err.prlink={name:'Enter a name or choose a contact.'};render();return}p=cwAddPerson({name:v.name,phone:v.phone,email:v.email,suburb:d.suburb,role:kind==='owner'?'seller':'buyer',source:'Agent',via:'property '+kind+' link'})}
 const x=cwDX(d);const arr=kind==='owner'?x.owners:x.purchasers;if(!arr.includes(p.id))arr.push(p.id);cwPX(p).linked=[...new Set([...(cwPX(p).linked||[]),d.id])];cwContactHistory(p,'Linked to '+d.address+' as '+kind);cwPrLog(d,cwCap(kind)+' added: '+p.name);ui.modal=null;cwPersist(cwCap(kind)+' added.')});
cwOn('cwPrUnlink',id=>{const [did,kind,pid]=id.split('|');const d=findD(did),x=cwDX(d);if(kind==='owner')x.owners=x.owners.filter(i=>i!==pid);else x.purchasers=x.purchasers.filter(i=>i!==pid);cwPrLog(d,cwCap(kind)+' removed: '+cwPName(pid));cwPersist('Removed.')});

/* enquiries, attendees, offers */
function cwPrTEnq(d){const sub=cwF('pr:enqsub','Enquiries');const enq=state.cw.enquiries.filter(e=>e.dealId===d.id),msgs=state.messages.filter(m=>m.dealId===d.id&&!enq.some(e=>e.msgId===m.id)),oh=state.cw.openHomes.filter(o=>o.dealId===d.id),att=oh.flatMap(o=>o.attendees.map(a=>({...a,day:o.day,oh:o.id}))),off=(state.offers||[]).filter(o=>o.dealId===d.id);
 const body=sub==='Attendees'?cwTable('pr:att',[['Name',a=>a.contactId?cwLink(h(a.name),'/contacts/'+a.contactId):h(a.name)],['Open home',a=>cwDate(a.day)],['Interest',a=>tag(a.temp||'','')],['Contract',a=>a.contract?tag('Requested','teal'):''],['Notes',a=>h(a.notes||'')],['',a=>cwGoBtn('Session','/open-home/'+a.oh,'sm')]],att,{empty:'No attendees yet'}):
  sub==='Offers'?cwTable('pr:off',[['Buyer',o=>cwLink(h(cwPName(o.buyerId)),'/contacts/'+o.buyerId)],['Amount',o=>h(cwMoney(o.amount))],['Terms',o=>h([o.deposit,o.finance,o.settlement].filter(Boolean).join(' · '))],['Status',o=>tag(o.status,/accept/i.test(o.status)?'green':/new/i.test(o.status)?'red':'')],['',()=>cwBtn('Review on Today','route','today','sm primary')]],off,{empty:'No offers yet'}):
  cwTable('pr:enq',[['Received',e=>cwDateTime(e.received)],['Type',e=>tag(e.type,'outline')],['Name',e=>e.contactId?cwLink(h(cwPName(e.contactId)),'/contacts/'+e.contactId):h(e.name||'')],['Source',e=>h(e.source)],['Comments',e=>h(e.comments||'')],['Status',e=>tag(e.status,e.status==='Pending'?'yellow':'green')],['',e=>e.status==='Pending'?cwBtn('Mark processed','cwPrEnqDone',e.id,'sm'):'']],enq,{empty:'No enquiries recorded for this property.'})+(msgs.length?cwCard('Conversations about this property',msgs.map(m=>`<div class="list-row"><div class="number-circle">${ico('messages','sm')}</div><div class="list-main"><strong>${h(cwPName(m.contactId))} · ${h(m.channel)}</strong><div class="sub">${h(m.last)}</div></div>${cwBtn('Open','selectMessage',m.id,'sm')}</div>`).join('')):'');
 return `${cwPills('pr:enqsub',[['Enquiries','Enquiries',enq.length],['Attendees','Attendees',att.length],['Offers','Offers',off.length]])}${body}`}
cwOn('cwPrEnqDone',id=>{const e=state.cw.enquiries.find(x=>x.id===id);if(!e)return;e.status='Processed';audit('enquiry','Enquiry processed: '+cwPName(e.contactId),e.type);cwPersist('Enquiry processed.')});

/* analytics */
function cwPrTAnalytics(d){const x=cwDX(d),per=cwF('pr:aper','Full campaign'),f=per==='7 days'?0.25:per==='30 days'?0.7:1;const v=Math.round(x.views*f),sv=Math.round(x.saves*f),en=Math.round(x.enquiries*f),of=(state.offers||[]).filter(o=>o.dealId===d.id).length,att=state.cw.openHomes.filter(o=>o.dealId===d.id).reduce((a,o)=>a+o.attendees.length,0);
 const score=Math.min(100,Math.round(v/4+sv*3+en*6+of*15+att*5));const steps=[['Viewed property',v],['Viewed gallery',Math.round(v*0.6)],['Saved',sv],['Enquired',en],['Attended open home',att],['Made an offer',of]];
 return `<div class="cw-row between">${cwPills('pr:aper',[['7 days','7 days'],['30 days','30 days'],['Full campaign','Full campaign']],'Full campaign')}${cwBtn('Generate vendor report','cwPrVendorReport',d.id,'primary')}</div>
 ${cwStats([['Campaign health',score+'/100',score>=60?'On track':score>=30?'Watch':'At risk',score<30?'highlight':''],['Total views',v],['Enquiries',en],['Saves',sv]])}
 <div class="cw-two">${cwCard('Buyer engagement funnel',`<div class="cw-funnel">${steps.map(([l,n])=>`<div><span>${l}</span><div class="cw-bar"><span style="width:${v?Math.round(n/Math.max(v,1)*100):0}%"></span></div><b>${n}</b></div>`).join('')}</div>`)}
 ${cwCard('Engagement over time',`<div class="cw-bars">${[...Array(10)].map((_,i)=>{const n=Math.round((cwHash(d.id+i)%10+1)*f*(x.views?1:0));return `<div><i style="height:${n*9}%"></i><span>W${i+1}</span></div>`}).join('')}</div>`)}
 ${cwCard('Where the buyers came from',cwKV([['realestate.com.au',Math.round(v*0.52)],['domain.com.au',Math.round(v*0.27)],['Collings portal',Math.round(v*0.15)],['Other',Math.round(v*0.06)]]))}
 ${cwCard('How this campaign compares',`<p class="small">${v?`${h(d.address)} has ${v} views over ${x.dom||1} days. The office average for ${h(x.type.toLowerCase())}s in ${h(d.suburb)} is about ${Math.round(v*0.9+20)}.`:'No property views recorded this month.'}</p>`)}</div>`}
cwOn('cwPrVendorReport',id=>{const d=findD(id);if(!d)return;const x=cwDX(d),v=findP(d.contactId);if(!v){toast('No vendor linked to this property.');return}if(state.actions.some(a=>a.dealId===d.id&&a.status==='Awaiting review'&&/vendor report/i.test(a.title))){toast('A vendor report for this property is already waiting on Today.');return}
 addAction({type:'Email',title:'Vendor report for '+d.address,body:`Hi ${v.name.split(' ')[0]},\n\nHere is this week's campaign update for ${d.address}: ${x.views} views, ${x.saves} saves, ${x.enquiries} enquiries and ${(state.offers||[]).filter(o=>o.dealId===d.id).length} written offers so far. I will call you to talk through feedback and next steps.\n\nCaleb Richards\nCollings Real Estate`,contactId:d.contactId,dealId:d.id,tier:'A2'});cwPersist('Vendor report drafted. It waits on Today for your approval.')});

/* notes */
function cwPrTNotes(d){const x=cwDX(d);return cwCard('Add New Note',`<textarea id="pr-note" class="field textarea full" placeholder="What happened, what was promised, what is next" aria-label="Add new note"></textarea><div class="cw-row" style="margin-top:8px"><label class="tiny muted" for="pr-note-kind">Type</label><select id="pr-note-kind" class="field cw-mini">${['General','Vendor','Buyer feedback','Price','Marketing'].map(k=>`<option>${k}</option>`).join('')}</select>${cwBtn('Add note','cwPrNoteAdd',d.id,'sm primary')}</div>`)+cwCard('Agent Notes ('+x.notes.length+')',x.notes.length?`<div class="cw-timeline">${x.notes.map(n=>`<div class="cw-tl"><span class="cw-tl-dot"></span><div style="flex:1"><b>${h(n.by)} ${n.kind?tag(n.kind,'outline'):''}</b><small>${cwDateTime(n.at)}</small><p>${h(n.text)}</p></div>${cwBtn('Delete','cwPrNoteDel',d.id+'|'+n.id,'sm ghost')}</div>`).join('')}</div>`:cwEmpty('No agent notes yet.'))}
cwOn('cwPrNoteAdd',id=>{const d=findD(id);const t=document.getElementById('pr-note')?.value.trim();if(!t){toast('Write the note first.');return}cwDX(d).notes.unshift({id:cwId('N'),text:t,kind:document.getElementById('pr-note-kind')?.value,by:CW_ME,at:cwNowISO()});cwPrLog(d,'Note added');if(/promis|call (back|on)|follow.?up|send (him|her|them)/i.test(t)&&!state.tasks.some(x=>x.dealId===d.id&&x.status==='Open'&&/from a property note/.test(x.origin||'')))addTask({title:'Follow up: '+t.slice(0,60),contactId:d.contactId,dealId:d.id,due:'Tomorrow',priority:'Normal',category:'Follow up',origin:'GeeVee · from a property note'});cwPersist('Note added.')});
cwOn('cwPrNoteDel',id=>{const [did,nid]=id.split('|');const d=findD(did);cwDX(d).notes=cwDX(d).notes.filter(n=>n.id!==nid);cwPersist('Note deleted.')});

/* photos */
function cwPrTPhotos(d){const x=cwDX(d);return cwCard('Property Photos',`<div class="cw-row" style="margin-bottom:12px"><label class="form-label" for="pr-photos" style="margin:0">Upload Photos</label><input id="pr-photos" type="file" class="field" multiple accept="image/*">${cwBtn('Upload','cwPrPhotoUp',d.id,'sm primary')}</div>${x.photos.length?`<div class="cw-gallery">${x.photos.map((p,i)=>`<figure><div class="cw-thumb big" style="height:96px;border-radius:0">${i===0?'Main image':''}</div><figcaption><span class="clip" title="${h(p.name)}">${h(p.name)}</span><span class="cw-row" style="gap:2px">${i?cwBtn('◀','cwPrPhotoMove',d.id+'|'+i+'|-1','sm ghost'):''}${i<x.photos.length-1?cwBtn('▶','cwPrPhotoMove',d.id+'|'+i+'|1','sm ghost'):''}${cwBtn('×','cwPrPhotoDel',d.id+'|'+p.id,'sm ghost')}</span></figcaption></figure>`).join('')}</div>`:cwEmpty('No images available for this property','Upload photos to use them in the listing and brochures.')}`)}
cwOn('cwPrPhotoUp',id=>{const d=findD(id);const fs=[...(document.getElementById('pr-photos')?.files||[])];if(!fs.length){toast('Choose one or more photos first.');return}fs.forEach(f=>cwDX(d).photos.push({id:cwId('PH'),name:f.name,at:cwNowISO()}));cwPrLog(d,fs.length+' photos uploaded');cwPersist(fs.length+' photos added. File names only in this prototype.')});
cwOn('cwPrPhotoMove',id=>{const [did,i,dir]=id.split('|');const ph=cwDX(findD(did)).photos;const a=Number(i),b=a+Number(dir);[ph[a],ph[b]]=[ph[b],ph[a]];cwPersist()});
cwOn('cwPrPhotoDel',id=>{const [did,pid]=id.split('|');const x=cwDX(findD(did));x.photos=x.photos.filter(p=>p.id!==pid);cwPersist('Photo removed.')});

/* open homes */
function cwPrTOpen(d){const list=state.cw.openHomes.filter(o=>o.dealId===d.id).sort((a,b)=>Date.parse(a.day)-Date.parse(b.day));
 return cwCard('Open Homes',cwTable('pr:oh',[['Day',o=>cwDate(o.day)],['Start',o=>h(o.start)],['End',o=>h(o.end)],['Primary Agent',o=>h(o.agent)],['Secondary Agents',o=>h(o.second||'None')],['Attendees',o=>o.attendees.length],['Status',o=>tag(o.status,o.status==='Upcoming'?'teal':'')],['',o=>`<div class="cw-row">${cwGoBtn('Session','/open-home/'+o.id,'sm')}${cwBtn('Delete','cwPrOhDel',o.id,'sm ghost')}</div>`]],list,{empty:'No open homes scheduled'}),cwBtn('Add open home','cwPrOhNew',d.id,'sm primary'))}
cwOn('cwPrOhNew',id=>cwModal('cwPrOh',id));
const CW_PR_OHF=()=>[{n:'date',l:'Date',t:'date',req:true},{n:'start',l:'Start',t:'time',req:true},{n:'end',l:'End',t:'time',req:true},{n:'agent',l:'Primary Agent',t:'select',o:cwAgentNames()},{n:'second',l:'Secondary Agent',t:'select',o:['',...cwAgentNames()]}];
cwModalDef('cwPrOh',id=>({title:'Add open home',body:cwForm('proh',CW_PR_OHF(),{date:cwLocalDay(new Date(Date.now()+3*864e5)),start:'10:00',end:'10:30',agent:CW_ME}),foot:cwBtn('Cancel','close')+cwBtn('Add open home','cwPrOhSave',id,'primary')}));
cwOn('cwPrOhSave',id=>{const d=findD(id);const v=cwRead('proh',CW_PR_OHF());if(!v)return;if(v.end<=v.start){cwU().draft.proh=v;cwU().err.proh={end:'End must be after start.'};render();return}const lab=t=>{const [H,M]=t.split(':').map(Number);return `${H%12||12}:${String(M).padStart(2,'0')}${H>=12?'pm':'am'}`};const day=new Date(v.date+'T'+v.start).toISOString();const o={id:cwId('OH'),dealId:d.id,day,start:lab(v.start),end:lab(v.end),agent:v.agent,second:v.second,status:'Upcoming',attendees:[]};state.cw.openHomes.push(o);cwDX(d).openHomes.push({id:o.id,day,start:o.start,end:o.end,agent:v.agent,second:v.second});cwPrLog(d,'Open home added '+cwDate(day)+' '+o.start);ui.modal=null;cwPersist('Open home added. It shows on the calendar and Inspections.')});
cwOn('cwPrOhDel',id=>{const o=state.cw.openHomes.find(x=>x.id===id);if(!o)return;if(o.attendees.length){toast('This session has attendees, so it is kept for the record.');return}state.cw.openHomes=state.cw.openHomes.filter(x=>x.id!==id);const d=findD(o.dealId);if(d){cwDX(d).openHomes=cwDX(d).openHomes.filter(x=>x.id!==id);cwPrLog(d,'Open home removed')}cwPersist('Open home removed.')});

/* documents */
function cwPrTDocs(d){const x=cwDX(d),cat=cwTab('pr:doccat','pps');return `${cwTabs('pr:doccat',CW_PR_DOCCATS.map(([k,l])=>[k,l,x.docs[k].length]))}
 <div class="cw-row" style="margin:12px 0"><input id="pr-doc" type="file" class="field" multiple aria-label="Choose documents">${cwBtn('Upload documents','cwPrDocUp',d.id,'sm primary')}${cwBtn('Email documents','cwPrDocEmail',d.id,'sm')}${cwBtn('Download all','cwPrDocAll',d.id,'sm')}</div>
 ${cwTable('pr:docs',[['Document',f=>`${ico('file','sm')} <b>${h(f.name)}</b>`],['Size',f=>h(f.size||'')],['Uploaded',f=>cwDate(f.at)],['By',f=>h(f.by||'')],['',f=>cwBtn('Delete','cwPrDocDel',d.id+'|'+cat+'|'+f.id,'sm ghost')]],x.docs[cat],{empty:'No '+CW_PR_DOCCATS.find(c=>c[0]===cat)[1]+' documents uploaded yet'})}`}
cwOn('cwPrDocUp',id=>{const d=findD(id);const fs=[...(document.getElementById('pr-doc')?.files||[])];if(!fs.length){toast('Choose a document first.');return}const cat=cwTab('pr:doccat','pps');fs.forEach(f=>cwDX(d).docs[cat].unshift({id:cwId('DOC'),name:f.name,size:Math.round(f.size/1024)+' KB',at:cwNowISO(),by:CW_ME}));if(cat==='pps')d.compliance['Property Price Statement']=true;if(cat==='contract')d.compliance['Contract of Sale + Section 32']=true;cwPrLog(d,fs.length+' documents uploaded to '+cat);cwPersist('Uploaded. File names only in this prototype.')});
cwOn('cwPrDocDel',id=>{const [did,cat,fid]=id.split('|');const x=cwDX(findD(did));x.docs[cat]=x.docs[cat].filter(f=>f.id!==fid);cwPersist('Document removed.')});
cwOn('cwPrDocAll',id=>{const x=cwDX(findD(id));const n=Object.values(x.docs).reduce((a,l)=>a+l.length,0);toast(n?`${n} documents would download as a zip in the live CRM.`:'There are no documents to download.')});
cwOn('cwPrDocEmail',id=>cwModal('cwPrDocMail',id));
cwModalDef('cwPrDocMail',id=>{const d=findD(id);const x=cwDX(d);const files=Object.values(x.docs).flat();return{title:'Email documents',body:files.length?cwForm('prmail',[{n:'to',l:'Send to',t:'select',o:cwContacts().filter(p=>!cwOptedOut(p)).map(p=>[p.id,p.name+' · '+p.email]),full:true},{n:'note',l:'Message',t:'textarea'}],{note:`Hi, here are the documents for ${d.address}, ${d.suburb}.`})+`<p class="hint">${files.length} documents attached. GeeVee puts the email on Today for your approval. Nothing is sent from here.</p>`:cwEmpty('No documents to send','Upload documents first.'),foot:cwBtn('Cancel','close')+(files.length?cwBtn('Prepare email','cwPrDocMailSave',id,'primary'):'')}});
cwOn('cwPrDocMailSave',id=>{const d=findD(id);const v=cwRead('prmail',[{n:'to',l:'Recipient',t:'select',req:true},{n:'note',l:'Message',t:'textarea',req:true}]);if(!v)return;const files=Object.values(cwDX(d).docs).flat().map(f=>f.name);addAction({type:'Email',title:'Send documents for '+d.address+' to '+cwPName(v.to),body:v.note+'\n\nAttached: '+files.join(', '),contactId:v.to,dealId:d.id,tier:'A2'});ui.modal=null;cwPersist('Email prepared. Approve it on Today.')});

/* compliance */
function cwPrTComp(d,base){const x=cwDX(d),miss=cwPrMissing(d),block=cwPrBlocking(d),pc=cwPrPriceCheck(d,x.priceLow,x.priceHigh);
 return `${block.length?cwNote('<b>Cannot Go Live.</b> '+block.map(h).join(' and ')+' missing. Residential sale, checked '+cwDateTime(x.compChecked||cwNowISO())+'.','danger'):miss.length?cwNote('<b>Can go live.</b> '+miss.length+' other items still to record.','warn'):cwNote('<b>All compliance items recorded.</b>','ok')}
 <div class="cw-row">${cwBtn('Re-check','cwPrRecheck',d.id,'sm')}${cwBtn('Export PDF','cwPrExport',d.id,'sm')}${cwBtn('Export all files','cwPrDocAll',d.id,'sm')}</div>
 ${cwCard('Listing compliance',CW_PR_COMP.map(k=>{const ok=(d.compliance||{})[k],na=(x.compNA||[]).includes(k);return `<div class="list-row"><div class="number-circle" style="${ok?'background:#e7f6eb;color:#217e50':''}">${ico(ok?'check':'file','sm')}</div><div class="list-main"><strong>${h(k)}</strong><div class="sub">${CW_PR_BLOCK.includes(k)?'Blocks go-live':'Optional for go-live'}${x.evidence?.[k]?' · Evidence: '+h(x.evidence[k]):''}</div></div><div class="action-side">${ok?tag('Received','green')+cwBtn('Undo','cwPrComp',d.id+'|'+k+'|undo','sm ghost'):na?tag('N/A','')+cwBtn('Applicable','cwPrComp',d.id+'|'+k+'|app','sm ghost'):`${tag('Not received','yellow')}${cwBtn('Record evidence','cwPrComp',d.id+'|'+k+'|rec','sm primary')}${CW_PR_BLOCK.includes(k)?'':cwBtn('N/A','cwPrComp',d.id+'|'+k+'|na','sm ghost')}`}</div></div>`}).join(''))}
 ${cwCard('Victorian price check',`${pc.ok?cwNote('Advertised price '+h(cwPrice(d))+' passes. Estimate on record: '+h(cwMoney(pc.est))+'.','ok'):cwNote(pc.problems.map(h).join('<br>'),'danger')}<div class="sep"></div><div class="cw-form" data-cwform="prpc"><div class="cw-grid"><div class="cw-ff"><label class="form-label" for="prpc-low">Proposed price from ($)</label><input id="prpc-low" name="low" type="number" class="field full" value="${h(cwF('pr:pcLow',x.priceLow))}"></div><div class="cw-ff"><label class="form-label" for="prpc-high">Proposed price to ($)</label><input id="prpc-high" name="high" type="number" class="field full" value="${h(cwF('pr:pcHigh',x.priceHigh))}"></div></div></div>${ui.cwPrPc?.id===d.id?(ui.cwPrPc.ok?cwNote('This proposed price passes. Applying it records a price event.','ok'):cwNote(ui.cwPrPc.problems.map(h).join('<br>')+'<br><b>DOMA blocks this price.</b>','danger')):''}<div class="cw-row" style="margin-top:10px">${cwBtn('Check price','cwPrPcRun',d.id,'sm')}${ui.cwPrPc?.id===d.id&&ui.cwPrPc.ok?cwBtn('Apply advertised price','cwPrPcApply',d.id,'sm primary'):''}</div><p class="hint" style="margin-top:8px">Rules: a single figure or a range of up to 10%, no qualifying words, never below the agent's estimate, the vendor's asking price or a written offer rejected as too low. Not legal advice.</p>`)}
 ${cwCard('Comparable sales',x.comps.length?cwTable('pr:comps',[['Address',c=>h(c[0])],['Price',c=>h(cwMoney(c[1]))],['Why chosen',c=>h(c[2])],['',(c)=>cwBtn('Remove','cwPrCompDel',d.id+'|'+x.comps.indexOf(c),'sm ghost')]],x.comps):cwEmpty('No comparables recorded yet.','Record the three comparable sales and why each was chosen.'),cwBtn('Add comparable','cwPrCompNew',d.id,'sm primary'))}
 ${cwCard('Price events',x.priceEvents.length?`<div class="cw-timeline">${x.priceEvents.map(e=>`<div class="cw-tl"><span class="cw-tl-dot"></span><div><b>${h(e.what)}</b><small>${cwDate(e.at)}</small><p>${h(e.value)}</p></div></div>`).join('')}</div>`:cwEmpty('No price events recorded yet.','The signed authority estimate, Property Price Statement indicative price, advertised price changes, reserve and rejected written offers appear here.'))}`}
cwOn('cwPrComp',id=>{const [did,k,op]=id.split('|');const d=findD(did),x=cwDX(d);x.compNA=x.compNA||[];x.evidence=x.evidence||{};
 if(op==='rec'){cwModal('cwPrEvidence',did+'|'+k);return}
 if(op==='undo')d.compliance[k]=false;if(op==='na')x.compNA.push(k);if(op==='app')x.compNA=x.compNA.filter(i=>i!==k);cwPrLog(d,'Compliance: '+k+' '+({undo:'set to not received',na:'marked N/A',app:'marked applicable'})[op]);cwPersist()});
cwModalDef('cwPrEvidence',id=>{const [,k]=id.split('|');return{title:'Record evidence: '+k,body:cwForm('prev',[{n:'evidence',l:'Evidence',req:true,full:true,ph:'Signed copy received by email 12 Nov'},{n:'file',l:'File (optional)',t:'file',full:true}]),foot:cwBtn('Cancel','close')+cwBtn('Record','cwPrEvSave',id,'primary')}});
cwOn('cwPrEvSave',id=>{const [did,k]=id.split('|');const v=cwRead('prev',[{n:'evidence',l:'Evidence',req:true},{n:'file',t:'file'}]);if(!v)return;const d=findD(did),x=cwDX(d);d.compliance[k]=true;x.evidence=x.evidence||{};x.evidence[k]=v.evidence+(v.file.length?' ('+v.file[0]+')':'');if(v.file.length){const cat=k==='Property Price Statement'?'pps':/Contract/.test(k)?'contract':'other';x.docs[cat].unshift({id:cwId('DOC'),name:v.file[0],size:'',at:cwNowISO(),by:CW_ME})}cwPrLog(d,'Compliance evidence recorded: '+k);ui.modal=null;cwPersist('Evidence recorded.')});
cwOn('cwPrRecheck',id=>{const d=findD(id);cwDX(d).compChecked=cwNowISO();const b=cwPrBlocking(d);cwPrLog(d,'Compliance re-checked: '+(b.length?'cannot go live':'can go live'));cwPersist(b.length?'Re-checked. Still blocked: '+b.join(', '):'Re-checked. This listing can go live.')});
cwOn('cwPrExport',id=>{const d=findD(id);toast('The compliance PDF for '+d.address+' would download in the live CRM.')});
cwOn('cwPrPcRun',id=>{const d=findD(id);const low=document.getElementById('prpc-low')?.value,high=document.getElementById('prpc-high')?.value;cwSetF('pr:pcLow',low);cwSetF('pr:pcHigh',high);ui.cwPrPc={id,low:Number(low),high:Number(high),...cwPrPriceCheck(d,low,high)};render()});
cwOn('cwPrPcApply',id=>{const d=findD(id),x=cwDX(d),r=ui.cwPrPc;if(!r||r.id!==id||!r.ok)return;x.priceLow=r.low;x.priceHigh=r.high||0;x.priceType=r.high?'Price Range':'Asking Price';d.guide=r.low;x.priceEvents.unshift({at:cwNowISO(),what:'Advertised price changed',value:cwPrice(d)});cwPrLog(d,'Advertised price set to '+cwPrice(d));if(x.docs.pps.length&&!state.tasks.some(t=>t.dealId===d.id&&t.status==='Open'&&/Property Price Statement/.test(t.title)))addTask({title:'Update the Property Price Statement for '+d.address,contactId:d.contactId,dealId:d.id,due:'Today',priority:'High',category:'Admin',origin:'GeeVee · advertised price changed'});ui.cwPrPc=null;delete cwU().f['pr:pcLow'];delete cwU().f['pr:pcHigh'];cwPersist('Advertised price applied and recorded.')});
cwOn('cwPrCompNew',id=>cwModal('cwPrComp',id));
cwModalDef('cwPrComp',id=>({title:'Add comparable sale',body:cwForm('prcomp',[{n:'address',l:'Address',req:true,full:true},{n:'price',l:'Sold price ($)',t:'number',req:true},{n:'why',l:'Why it was chosen',req:true,full:true}])+`<p class="hint">Recent nearby sales on record: ${state.cw.sales.filter(s=>s.suburb===findD(id)?.suburb).map(s=>h(s.address)+' '+cwShort(s.price)).join(', ')||'none in this suburb'}.</p>`,foot:cwBtn('Cancel','close')+cwBtn('Add','cwPrCompSave',id,'primary')}));
cwOn('cwPrCompSave',id=>{const v=cwRead('prcomp',[{n:'address',l:'Address',req:true},{n:'price',l:'Price',t:'number',req:true},{n:'why',l:'Why',req:true}]);if(!v)return;const d=findD(id);cwDX(d).comps.push([v.address,Number(v.price),v.why]);if(cwDX(d).comps.length>=3)d.compliance['Pricing / comparable-sales evidence']=true;cwPrLog(d,'Comparable added: '+v.address);ui.modal=null;cwPersist('Comparable added.')});
cwOn('cwPrCompDel',id=>{const [did,i]=id.split('|');const d=findD(did);cwDX(d).comps.splice(Number(i),1);cwPersist('Comparable removed.')});

/* typeform */
function cwPrTType(d){const t=cwDX(d).typeform;if(!t)return cwCard('TypeForm Answers',cwEmpty('No answers recorded.','Answers arrive when the vendor completes the Block of Units information form.',cwBtn('Enter answers','cwPrTfNew',d.id,'primary')+cwBtn('Ask the vendor to complete it','cwPrTfAsk',d.id,'')));
 const gross=Number(t.rent||0)*52,net=gross-Number(t.outgoings||0),price=cwPrEstimate(d);
 return cwCard('Key Numbers',cwKV([['Units',t.units],['Bedrooms (total)',t.beds],['Car spaces (total)',t.cars],['Tenanted',t.tenanted],['Vacant',t.vacant],['Owner occupied',t.owner],['Rent / week',t.rent?cwMoney(t.rent):''],['Gross rent p.a.',gross?cwMoney(gross):''],['Total outgoings p.a.',t.outgoings?cwMoney(t.outgoings):''],['Net rent p.a.',gross?cwMoney(net):''],['Price (estimate)',cwMoney(price)],['Gross yield',price&&gross?(gross/price*100).toFixed(2)+'%':'N/A'],['Net yield',price&&gross?(net/price*100).toFixed(2)+'%':'N/A']]),cwBtn('Edit answers','cwPrTfNew',d.id,'sm'))+cwCard('All Answers',cwKV(Object.entries(t.answers||{}).map(([k,v])=>[k,h(v)])))}
const CW_PR_TF=[{n:'units',l:'Units',t:'number',req:true},{n:'beds',l:'Bedrooms (total)',t:'number'},{n:'cars',l:'Car spaces (total)',t:'number'},{n:'tenanted',l:'Tenanted',t:'number'},{n:'vacant',l:'Vacant',t:'number'},{n:'owner',l:'Owner occupied',t:'number'},{n:'rent',l:'Rent per week, all units ($)',t:'number'},{n:'outgoings',l:'Total outgoings per year ($)',t:'number'}];
cwOn('cwPrTfNew',id=>cwModal('cwPrTf',id));
cwModalDef('cwPrTf',id=>({title:'TypeForm answers',body:cwForm('prtf',CW_PR_TF,cwDX(findD(id)).typeform||{}),foot:cwBtn('Cancel','close')+cwBtn('Save answers','cwPrTfSave',id,'primary')}));
cwOn('cwPrTfSave',id=>{const v=cwRead('prtf',CW_PR_TF);if(!v)return;const d=findD(id);cwDX(d).typeform={...v,answers:{'Entered by':CW_ME,'Entered on':cwDate(new Date())}};cwPrLog(d,'TypeForm answers recorded');ui.modal=null;cwPersist('Answers saved.')});
cwOn('cwPrTfAsk',id=>{const d=findD(id),p=findP(d.contactId);if(!p||cwOptedOut(p)){toast('No contactable vendor on this property.');return}addAction({type:'Email',title:'Ask '+p.name+' for the units information form',body:`Hi ${p.name.split(' ')[0]}, could you complete this short form about ${d.address} so we can price it accurately: [form link]. Caleb, Collings.`,contactId:p.id,dealId:d.id,tier:'A2'});cwPersist('Request drafted. Approve it on Today.')});

/* buyer match */
function cwPrPrefMatch(d){const x=cwDX(d);const sub=cwF('pr:bmSub',d.suburb),lo=Number(cwF('pr:bmLo',''))||0,hi=Number(cwF('pr:bmHi',''))||0,beds=Number(cwF('pr:bmBeds',x.beds))||0,rad=Number(cwF('pr:bmRad','5'));
 const near=[sub,...(rad>=5?CW_NEAR[sub]||[]:[])];
 return cwContacts().filter(p=>p.role!=='seller'&&cwPX(p).prefs).map(p=>{const pr=cwPX(p).prefs,why=[];if(pr.suburbs.some(s=>near.includes(s)))why.push('Looking in '+pr.suburbs.join(', '));if(d.guide>=pr.priceMin&&d.guide<=pr.priceMax)why.push('Budget '+cwShort(pr.priceMin)+' to '+cwShort(pr.priceMax));if(pr.beds<=x.beds)why.push('Wants '+pr.beds+'+ bedrooms');const lb=(!lo||pr.priceMax>=lo)&&(!hi||pr.priceMin<=hi)&&pr.beds>=0&&x.beds>=Math.min(beds,pr.beds);return{p,why,ok:why.length>=2&&lb}}).filter(r=>r.ok).sort((a,b)=>b.why.length-a.why.length)}
function cwPrTMatch(d){const x=cwDX(d),live=cwPrListedLive(d),rows=cwPrPrefMatch(d);
 return `${cwCard('Find Buyers for a Property',`<div class="cw-grid">${[['pr:bmSub','Suburb',d.suburb],['pr:bmLo','Price from ($)',''],['pr:bmHi','Price to ($)',''],['pr:bmBeds','Bedrooms at least',x.beds]].map(([k,l,def])=>`<div class="cw-ff"><label class="form-label" for="cwb-${cwSlug(k)}">${l}</label>${cwInput(k,l,{cls:'full',def:String(def)})}</div>`).join('')}<div class="cw-ff"><label class="form-label" for="cwb-pr_bmRad">Radius</label>${cwSelect('pr:bmRad',[['2','2 km'],['5','5 km'],['10','10 km'],['15','15 km'],['25','25 km']],{def:'5',cls:'full'})}</div></div>`)}
 ${cwCard('Buyers with a recorded reason',typeof gvxBuyerRows==='function'?gvxBuyerRows(d):'')}
 ${cwCard('Buyers whose saved preferences match',rows.length?rows.map(r=>{const op=cwOptedOut(r.p),done=state.actions.some(a=>a.contactId===r.p.id&&a.dealId===d.id&&a.status==='Awaiting review');return `<div class="list-row">${cwAvatar(r.p.name)}<div class="list-main"><strong>${cwLink(h(r.p.name),'/contacts/'+r.p.id)}</strong><div class="sub">${r.why.map(h).join(' · ')}</div></div><div class="action-side">${op?tag('Opted out. Do not contact.','red'):`${cwBtn('Call','call',r.p.id,'sm')}${live?(done?tag('Draft on Today','yellow'):cwBtn('Draft text','cwPrDraftBuyer',r.p.id+'|'+d.id,'sm')):''}`}</div></div>`}).join(''):cwEmpty('No Buyer Matches Found','No buyer preferences match these criteria. Widen the radius or price.'))}`}
cwOn('cwPrDraftBuyer',id=>{const [pid,did]=id.split('|');const p=findP(pid),d=findD(did);if(!p||!d)return;if(cwOptedOut(p)){toast(p.name+' has opted out. GeeVee will not draft marketing.');return}if(!cwPrListedLive(d)){toast(d.address+' is not advertised yet, so no marketing drafts.');return}if((state.offers||[]).some(o=>o.dealId===d.id&&o.buyerId===p.id&&!/declin|withdraw|reject/i.test(o.status))){toast(p.name+' has a live offer. Call them, no marketing.');return}
 const body=typeof gvxBuyerDraft==='function'?gvxBuyerDraft(p,d,'SMS').body:`Hi ${p.name.split(' ')[0]}, ${d.address}, ${d.suburb} may suit what you are looking for. Would you like the details? Caleb, Collings. Reply STOP to opt out.`;
 addAction({type:'SMS',title:'Text '+p.name+' about '+d.address,body,contactId:p.id,dealId:d.id,tier:'A2'});cwPersist('Draft is on Today for your approval.')});

/* notifications + activity */
function cwPrTNotify(d){const x=cwDX(d),n=x.notify||{enquiries:true,offers:true,views:false};const list=state.cw.notifications.filter(m=>(m.title+' '+m.body).includes(d.address));
 return cwCard('Notify me about this property',[['enquiries','New enquiries'],['offers','Written offers'],['views','Big jumps in views']].map(([k,l])=>`<div class="list-row"><div class="list-main"><strong>${l}</strong></div>${n[k]?tag('On','green'):tag('Off','')}${cwBtn(n[k]?'Turn off':'Turn on','cwPrNotify',d.id+'|'+k,'sm')}</div>`).join(''))+cwCard('Recent notifications',list.length?list.map(m=>`<div class="list-row"><div class="number-circle">${ico('bell','sm')}</div><div class="list-main"><strong>${h(m.title)}</strong><div class="sub">${cwDateTime(m.at)}</div></div></div>`).join(''):cwEmpty('No notifications for this property yet.'))}
cwOn('cwPrNotify',id=>{const [did,k]=id.split('|');const x=cwDX(findD(did));x.notify=x.notify||{enquiries:true,offers:true,views:false};x.notify[k]=!x.notify[k];cwPersist('Notification setting saved.')});
function cwPrTActivity(d){const x=cwDX(d);const ev=[...x.activity.map(a=>({at:a.at,by:a.by,what:a.what})),...state.activity.filter(a=>(a.title+' '+(a.details||'')).includes(d.address)).map(a=>({at:null,when:a.when,by:'GeeVee log',what:a.title}))];
 return cwCard('Activity',ev.length?`<div class="cw-timeline">${ev.slice(0,60).map(e=>`<div class="cw-tl"><span class="cw-tl-dot"></span><div><b>${h(e.what)}</b><small>${e.at?cwDateTime(e.at):h(e.when||'')} · ${h(e.by||'')}</small></div></div>`).join('')}</div>`:cwEmpty('No activity recorded yet.','Changes to this property will appear here.'))}

/* header actions */
cwOn('cwPrDup',id=>{const [did,base]=id.split('|');const d=findD(did);if(!d)return;const n=state.deals.length+3001;const c=structuredClone(d);c.id='D-'+n;c.legacyId='NEW';c.address=d.address+' (copy)';c.stage='Appraisal';c.active=true;c.lastChange='Just now';c.compliance=Object.fromEntries(CW_PR_COMP.map(k=>[k,false]));const x=c.cw;x.status='Appraisal';x.notes=[];x.activity=[];x.docs={pps:[],contract:[],lease:[],report:[],other:[]};x.openHomes=[];x.purchasers=[];x.trashed=false;x.listedAt=cwNowISO();state.deals.push(c);cwPrLog(c,'Duplicated from '+d.address);persist();cwGo(base+'/edit/'+c.id);toast('Copy created. Update the address and details.')});
cwOn('cwPrArticle',id=>{const d=findD(id);state.cw.seo=state.cw.seo||[];if(state.cw.seo.some(a=>a.dealId===id&&a.status==='Draft')){toast('A draft article for this property already exists in AI-SEO.');return}state.cw.seo.unshift({id:cwId('SEO'),title:`${cwDX(d).headline} in ${d.suburb}: ${d.address}`,dealId:id,status:'Draft',at:cwNowISO(),words:420});cwPrLog(d,'Article drafted for AI-SEO');cwPersist('Draft article created from the property record. Review it in AI-SEO before publishing.')});
cwOn('cwPrWithdraw',id=>{const d=findD(id);cwConfirm('Withdraw '+d.address+'?','The listing comes off the market and is hidden from portals. Nothing is deleted, and you can relist from Edit.','cwPrWithdrawYes',id,'Withdraw','warn')});
cwOn('cwPrWithdrawYes',id=>{const d=findD(id),x=cwDX(d);d.stage='Lost';d.active=false;x.status='Withdrawn';x.visibility=false;x.channels={...(x.channels||{}),rea:false,domain:false,collings:false};cwPrLog(d,'Withdrawn from sale');ui.modal=null;cwPersist('Withdrawn from sale.')});
cwOn('cwPrContract',id=>{const d=findD(id);cwConfirm('Mark '+d.address+' under contract?','The listing shows as under contract. Record the sale with Mark as sold once it is unconditional.','cwPrContractYes',id,'Under contract','primary')});
cwOn('cwPrContractYes',id=>{const d=findD(id);cwDX(d).status='Under Contract';cwPrLog(d,'Marked under contract');ui.modal=null;cwPersist('Marked under contract.')});
cwOn('cwPrSold',id=>cwModal('cwPrSold',id));
cwModalDef('cwPrSold',id=>{const d=findD(id);return{title:'Mark as sold: '+d.address,body:cwForm('prsold',[{n:'price',l:'Sale price ($)',t:'number',req:true},{n:'date',l:'Date unconditional',t:'date',req:true},{n:'buyer',l:'Purchaser',t:'select',o:[['','Not recorded'],...cwContacts().filter(p=>p.role!=='seller').map(p=>[p.id,p.name])]},{n:'portal',l:'Sold through the Collings portal',t:'check'}],{price:d.guide,date:cwLocalDay()})+cwNote('Victoria: the sold price must be published in the Property Price Statement within 7 days of the sale going unconditional. DOMA adds that task.','info'),foot:cwBtn('Cancel','close')+cwBtn('Mark as sold','cwPrSoldSave',id,'primary')}});
cwOn('cwPrSoldSave',id=>{const v=cwRead('prsold',[{n:'price',l:'Sale price',t:'number',req:true},{n:'date',l:'Date',t:'date',req:true},{n:'buyer',t:'select'},{n:'portal',t:'check'}]);if(!v)return;const d=findD(id),x=cwDX(d);d.stage='Sold';d.active=false;x.status='Sold';x.soldPrice=Number(v.price);x.soldAt=v.date;x.soldPortal=v.portal;if(v.buyer&&!x.purchasers.includes(v.buyer))x.purchasers.push(v.buyer);x.priceEvents.unshift({at:cwNowISO(),what:'Sold',value:cwMoney(v.price)});
 state.cw.settlements=state.cw.settlements||[];state.cw.settlements.push({id:cwId('ST'),dealId:d.id,commission:Math.round(Number(v.price)*(d.fee||1.85)/100),settles:cwLocalDay(new Date(Date.parse(v.date)+60*864e5))});
 const due=new Date(Date.parse(v.date)+7*864e5);addTask({title:'Publish the sold price in the Property Price Statement for '+d.address,contactId:d.contactId,dealId:d.id,dueISO:cwLocalDay(due),due:cwDate(due),priority:'High',category:'Admin',origin:'Victorian rule: within 7 days of unconditional'});
 cwPrLog(d,'Marked as sold for '+cwMoney(v.price));ui.modal=null;cwPersist('Sold. Settlement and the 7-day Property Price Statement task were added.')});
cwOn('cwPrDelete',id=>{const [did,base]=id.split('|');const d=findD(did);cwConfirm('Move '+d.address+' to the trash?','It stays in the trash for 180 days and can be restored with its notes and documents.','cwPrDeleteYes',id,'Move to trash','warn')});
cwOn('cwPrDeleteYes',id=>{const [did,base]=id.split('|');const d=findD(did);cwDX(d).trashed=true;cwDX(d).trashedAt=cwNowISO();cwPrLog(d,'Moved to trash');ui.modal=null;persist();cwGo(base);toast('Moved to trash.')});

/* ---------- public properties (database profiles) ---------- */
function cwPrUni(){const out=[];for(const d of cwProps())out.push({key:d.id,kind:'CRM listing',address:d.address,suburb:d.suburb,type:cwDX(d).type,beds:cwDX(d).beds,baths:cwDX(d).baths,price:d.guide,status:cwDX(d).status,owner:cwPName(d.contactId),ownerId:d.contactId,dealId:d.id,market:d.stage==='For sale'?'For Sale':d.stage==='Sold'?'Sold':d.stage==='Listed'?'Off Market':'Off Market'});
 for(const r of state.cw.db.records)out.push({key:r.id,kind:'Owner database',address:r.address,suburb:r.suburb,type:r.type,beds:r.beds,baths:r.baths,price:0,lastSold:r.lastSold,status:'Database record',owner:r.owner,ownerPhone:r.mobile,rec:r,market:r.market==='Withdrawn'?'Off Market':'Off Market'});
 for(const s of state.cw.sales)out.push({key:s.id,kind:'Recent sale',address:s.address,suburb:s.suburb,type:'House',beds:s.beds,baths:s.baths,price:s.price,lastSold:cwMoney(s.price)+' ('+cwDate(s.date)+')',status:'Sold',owner:'',market:'Sold'});
 for(const r of state.cw.relisting)if(!out.some(o=>o.address===r.address))out.push({key:r.id,kind:'Re-listing signal',address:r.address,suburb:r.suburb,type:'House',beds:3,baths:1,price:r.price,status:r.kind,owner:r.owner,ownerId:r.ownerId,market:r.kind==='Withdrawn'?'Off Market':'For Sale'});
 return out}
function cwPrUniGet(id){const all=cwPrUni();return all.find(u=>u.key===id)||(['1','sample'].includes(String(id))?all.find(u=>u.kind==='Owner database')||all[0]:null)}
cwPage('/public-properties',{title:'Public properties',group:'props',render(){const q=cwF('pp:q','');let list=cwPrUni();list=cwSearchRows(list,q,u=>u.address+' '+u.suburb+' '+(CW_POSTCODES[u.suburb]||'')+' '+u.owner);
 return `${cwHeader('Public Properties','Every property in your Database, as its own profile. Kept separate from your appraisals and listings.')}
 <div class="toolbar">${cwInput('pp:q','Search an address, street, suburb, postcode or owner')}<span class="tiny muted">${list.length} profiles</span></div>
 ${cwTable('pp:list',[['Address',u=>`<b>${cwLink(h(u.address),'/public-properties/'+u.key)}</b><div class="tiny muted">${h(u.suburb)}</div>`,u=>u.address],['Source',u=>tag(u.kind,'outline'),u=>u.kind],['Type',u=>h(u.type)],['Beds',u=>u.beds,u=>u.beds],['Last sold',u=>h(u.lastSold||'')],['Owner',u=>u.ownerId?cwLink(h(u.owner),'/contacts/'+u.ownerId):h(u.owner||'')],['',u=>cwGoBtn('Profile','/public-properties/'+u.key,'sm')]],list,{empty:'No Public Properties yet'})}`},
 ai(){const u=cwPrUni();const both=u.filter(a=>a.kind!=='CRM listing'&&u.some(b=>b.kind==='CRM listing'&&b.address===a.address));return[{k:'auto',t:'Profiles joined across sources',b:u.length+' profiles from listings, the owner database, recent sales and re-listing signals.'},both.length?{k:'info',t:both.length+' addresses appear in more than one source',b:both.map(a=>h(a.address)).join('<br>')+'<br>Duplicate check can merge them.',a:[['Duplicate check','cwGo','/duplicate-check']]}:null]}});
function cwPrProfile(ctx,base){const u=cwPrUniGet(ctx.params.id);if(!u)return cwHeader('Property profile not found','',cwGoBtn('Back',base,'primary'));const lc=state.cw.landchecker;const data=(state.cw.prData||{})[u.key];
 return `${cwHeader(h(u.address)+', '+h(u.suburb),tag(u.kind,'teal')+' '+h(u.status),`${u.dealId?cwGoBtn('Open CRM listing','/properties/'+u.dealId+'?tab=property','primary'):cwBtn('Add to prospects','cwPrToProspect',u.key,'primary')}${cwBtn('Get property data','cwPrGetData',u.key,'')}`)}
 <div class="cw-two">${cwCard('Property',cwKV([['Type',h(u.type)],['Bedrooms',u.beds],['Bathrooms',u.baths],['Last sold',h(u.lastSold||'')],['Estimate or price',u.price?cwMoney(u.price):''],['Source',h(u.kind)]]))}
 ${cwCard('Owner',u.ownerId?`${cwKV([['Name',cwLink(h(u.owner),'/contacts/'+u.ownerId)],['Phone',h(findP(u.ownerId)?.phone||'')]])}`:u.owner?cwKV([['Name',h(u.owner)],['Mobile',h(u.ownerPhone||'')],['Permission',h(u.rec?.permission||'')],['Do not contact',u.rec?.dnc?tag('Yes','red'):'No']]):cwEmpty('No owner on file'))}</div>
 ${cwCard('Land and planning',data?cwKV([['Land size',data.land+' m²'],['Zone',data.zone],['Overlays',data.overlays],['Council',data.council],['Fetched',cwDateTime(data.at)]]):`<p class="small muted">${lc.on?'Press "Get property data" for land, zoning and overlays (one Landchecker call).':'Landchecker lookups are switched off by an admin.'}</p>`)}
 ${cwCard('Sales history',state.cw.sales.filter(s=>s.address===u.address).map(s=>`<div class="list-row"><div class="list-main"><strong>${cwMoney(s.price)}</strong><div class="sub">${cwDate(s.date)}</div></div></div>`).join('')||cwEmpty('No sales recorded for this address.'))}`}
