function cwPrAiQuery(q){const l=q.toLowerCase();const o={};const b=l.match(/(\d)\s*(\+\s*)?bed/);if(b)o.beds=Number(b[1]);const p=l.match(/(under|below|max|less than)\s*\$?([\d.]+)\s*(m|k)?/);if(p){let n=Number(p[2]);if(p[3]==='m')n*=1e6;else if(p[3]==='k')n*=1e3;else if(n<20)n*=1e6;o.max=n}for(const s of Object.keys(CW_POSTCODES))if(l.includes(s.toLowerCase()))o.suburb=s;for(const t of ['house','townhouse','unit','apartment'])if(l.includes(t))o.type=cwCap(t);const words=l.replace(/\d+\s*\+?\s*bed\w*|(under|below|max|less than)\s*\$?[\d.]+\s*(m|k)?/g,'').split(/\s+/).filter(w=>w.length>3&&!['with','near','home','homes','property','properties'].includes(w)&&!Object.keys(CW_POSTCODES).some(s=>s.toLowerCase().includes(w))&&!['house','townhouse','unit','apartment'].includes(w));o.words=words;return o}
