/* ---------- duplicate check ---------- */
function cwPrNormAddr(a){return String(a||'').toLowerCase().replace(/\(copy\)/g,'').replace(/\bstreet\b/g,'st').replace(/\broad\b/g,'rd').replace(/\bavenue\b/g,'ave').replace(/[^a-z0-9/ ]/g,'').replace(/\s+/g,' ').trim()}
function cwPrDupGroups(kind){const ign=(state.cw.dupIgnore||[]);const g={};
 if(kind==='Property'){for(const d of cwProps()){const k=cwPrNormAddr(d.address)+'|'+d.suburb.toLowerCase();(g[k]=g[k]||[]).push({id:d.id,label:d.address+', '+d.suburb,sub:d.stage+' · '+cwPName(d.contactId),route:'/properties/'+d.id})}}
 else{for(const p of cwContacts()){const keys=[p.phone?'ph:'+p.phone.replace(/\D/g,''):'',p.email?'em:'+p.email.toLowerCase():'','nm:'+p.name.toLowerCase().replace(/[^a-z]/g,'')].filter(Boolean);for(const k of keys)(g[k]=g[k]||[]).push({id:p.id,label:p.name,sub:p.phone+' · '+p.email,route:'/contacts/'+p.id})}}
 const seen=new Set();return Object.entries(g).filter(([k,v])=>v.length>1&&!ign.includes(k)).map(([k,v])=>({key:k,items:v.filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i)})).filter(x=>x.items.length>1).filter(x=>{const s=x.items.map(i=>i.id).sort().join();if(seen.has(s))return false;seen.add(s);return true})}
cwPage('/duplicate-check',{title:'Duplicate check',group:'props',render(){const kind=cwF('dup:kind','Property'),view=cwF('dup:view','check'),q=cwF('dup:q','');let groups=cwPrDupGroups(kind);if(q)groups=groups.filter(g=>g.items.some(i=>(i.label+' '+i.sub).toLowerCase().includes(q.toLowerCase())));
 const merged=state.cw.dupMerged||[],ign=state.cw.dupIgnore||[];
 return `${cwHeader('Duplicate Check','Find and merge records that are the same property or person.',cwBtn(ico('refresh','sm')+' Refresh','cwPrDupRefresh','',''))}
 <div class="toolbar">${cwPills('dup:kind',[['Property','Q Property'],['Contact','Q Contact']])}${cwPills('dup:view',[['check','Duplicate Check'],['merged','Recently Merged',merged.length],['ignored','Ignore List',ign.length]])}${cwInput('dup:q','Search properties or contacts')}</div>
 ${view==='merged'?cwCard('Recently merged',merged.length?merged.map(m=>`<div class="list-row"><div class="list-main"><strong>${h(m.kept)}</strong><div class="sub">Merged ${m.count} records · ${cwDateTime(m.at)}</div></div></div>`).join(''):cwEmpty('Nothing merged yet')):
  view==='ignored'?cwCard('Ignore list',ign.length?ign.map(k=>`<div class="list-row"><div class="list-main"><strong>${h(k.replace(/^\w\w:/,''))}</strong></div>${cwBtn('Stop ignoring','cwPrDupUnignore',k,'sm')}</div>`).join(''):cwEmpty('The ignore list is empty')):
  `<h2 style="font-size:15px">Results</h2><p class="small muted">Found ${groups.length} duplicate group(s).</p>${groups.length?groups.map(g=>cwCard('Group: '+h(g.key.replace(/^\w\w:/,'').split('|')[0]),g.items.map((i,n)=>`<div class="list-row"><div class="list-main"><strong>${cwLink(h(i.label),i.route)}</strong><div class="sub">${h(i.sub)} ${n===0?tag('Kept on merge','teal'):''}</div></div></div>`).join(''),`<div class="cw-row">${cwBtn('Merge','cwPrDupMerge',kind+'|'+g.items.map(i=>i.id).join(','),'sm primary')}${cwBtn('Ignore','cwPrDupIgnore',g.key,'sm')}</div>`)).join(''):cwEmpty('No Duplicates Found','No duplicate '+(kind==='Property'?'properties':'contacts')+' were detected in the system.')}`}`},
 ai(){const p=cwPrDupGroups('Property').length,c=cwPrDupGroups('Contact').length;return[{k:p+c?'check':'auto',t:p+c?`${p} property and ${c} contact duplicate groups`:'No duplicates found',b:'GeeVee checks addresses, phone numbers, emails and names every time a record is added. Merging keeps the first record and moves tasks, messages and approvals onto it.'}]}});
cwOn('cwPrDupRefresh',()=>{audit('auto','Duplicate check re-run','Properties and contacts.');render();toast('Duplicate check refreshed.')});
cwOn('cwPrDupIgnore',k=>{state.cw.dupIgnore=[...(state.cw.dupIgnore||[]),k];cwPersist('Group ignored.')});
cwOn('cwPrDupUnignore',k=>{state.cw.dupIgnore=(state.cw.dupIgnore||[]).filter(x=>x!==k);cwPersist('Removed from the ignore list.')});
cwOn('cwPrDupMerge',id=>{const [kind,list]=id.split('|');const ids=list.split(',');const keep=ids[0],rest=ids.slice(1);const fld=kind==='Property'?'dealId':'contactId';
 for(const coll of [state.tasks,state.messages,state.actions,state.cw.enquiries])for(const r of coll)if(rest.includes(r[fld]))r[fld]=keep;
 if(kind==='Property'){for(const r of state.cw.openHomes)if(rest.includes(r.dealId))r.dealId=keep;const k=findD(keep);for(const rid of rest){const d=findD(rid);if(!d)continue;cwDX(k).notes.push(...cwDX(d).notes);cwDX(d).trashed=true;cwDX(d).trashedAt=cwNowISO()}cwPrLog(k,'Merged '+rest.length+' duplicate records')}
 else{for(const d of state.deals){if(rest.includes(d.contactId))d.contactId=keep;const x=cwDX(d);x.owners=x.owners.map(o=>rest.includes(o)?keep:o)}const k=findP(keep);for(const rid of rest){const p=findP(rid);if(!p)continue;cwPX(k).notes.push(...cwPX(p).notes);cwPX(p).trashed=true;cwPX(p).trashedAt=cwNowISO()}cwContactHistory(k,'Merged '+rest.length+' duplicate contacts')}
 state.cw.dupMerged=[{kept:kind==='Property'?findD(keep)?.address:findP(keep)?.name,count:ids.length,at:cwNowISO()},...(state.cw.dupMerged||[])];audit('merge','Merged '+ids.length+' duplicate '+kind.toLowerCase()+' records','Kept '+keep+'. Others moved to trash.');cwPersist('Merged. The other records are in the trash.')});

